import csv
import json
import sys
import os


class HarnessError(Exception):
    \"\"\"Indicates a harness processing failure.\"\"\"
    pass


def run_dag(source_files):
    \"\"\"Process CSV and JSONL files, return report dict.

    Args:
        source_files: list of relative file paths

    Returns:
        dict with processed_count, rejected_count, retry_count, source_files

    Raises:
        HarnessError: on file read failure
    \"\"\"
    processed = 0
    rejected = 0

    for filepath in source_files:
        if not os.path.isfile(filepath):
            raise HarnessError(\"file not found: \" + filepath)

        ext = os.path.splitext(filepath)[1].lower()
        if ext == \".csv\":
            p, r = _read_csv(filepath)
        elif ext == \".jsonl\":
            p, r = _read_jsonl(filepath)
        else:
            raise HarnessError(\"unsupported file type: \" + ext)

        processed += p
        rejected += r

    return {
        \"processed_count\": processed,
        \"rejected_count\": rejected,
        \"retry_count\": 0,
        \"source_files\": source_files,
    }


def _find_id_key(fieldnames):
    \"\"\"Find the id column case-insensitively.\"\"\"
    for name in fieldnames:
        if name.strip().lower() == \"id\":
            return name
    return None


def _read_csv(filepath):
    processed = 0
    rejected = 0
    with open(filepath, \"r\", newline=\"\", encoding=\"utf-8\") as f:
        reader = csv.DictReader(f)
        id_key = _find_id_key(reader.fieldnames or [])
        for row in reader:
            if all(v is None or (isinstance(v, str) and v.strip() == \"\") for v in row.values()):
                continue
            if id_key is not None and row.get(id_key) is not None and row[id_key].strip() "'!= "":
                processed += 1
            else:
                rejected += 1
    return processed, rejected


def _read_jsonl(filepath):
    processed = 0
    rejected = 0
    with open(filepath, "r", encoding="utf-8") as f:
        for line in f:
            stripped = line.strip()
            if not stripped:
                continue
            try:
                obj = json.loads(stripped)
            except json.JSONDecodeError:
                rejected += 1
                continue
            if "id" in obj and obj["id"] is not None and str(obj["id"]).strip() != "":
                processed += 1
            else:
                rejected += 1
    return processed, rejected
